def trajectory(nodes, speed=90):
    n=np.array(nodes,float)
    seg=np.linalg.norm(np.diff(n[:,:2],axis=0),axis=1)
    # param interpolate spatial and width (PCHIP)
    t=np.r_[0,np.cumsum(np.maximum(seg,3))]
    tt=np.linspace(0,t[-1],max(2,int(t[-1]/speed*100)+1))
    out=PchipInterpolator(t,n,axis=0)(tt)
    tangent=PchipInterpolator(t,n[:,:2],axis=0).derivative()(tt)
    tangent/=np.maximum(np.linalg.norm(tangent,axis=1)[:,None],1e-9)
    # depth mm from desired width
    depth=(out[:,2]*PX+.3)/1.187
    offset=np.maximum(0,11.15-9.67*(np.minimum(depth,15)/10-1.091)**2)/PX
    tips=out[:,:2]+offset[:,None]*tangent
    # preceding descent and final ascent, fixed xy, at 12mm/s
    p=np.column_stack([tips,depth])
    before=np.column_stack([np.tile(tips[0],(int((depth[0]+1)/.12)+1,1)),np.linspace(-1,depth[0],int((depth[0]+1)/.12)+1)])
    after=np.column_stack([np.tile(tips[-1],(int((depth[-1]+1)/.12)+1,1)),np.linspace(depth[-1],-1,int((depth[-1]+1)/.12)+1)])
    return np.ascontiguousarray(np.r_[before,p,after],dtype=np.float64)

def build():
    os.system('g++ -O3 -shared -fPIC /app/output/model.cpp -o /app/output/model.so')
lib=None
def render(nodes,scale=2):
    global lib
    if lib is None:
        lib=ctypes.CDLL('/app/output/model.so');lib.draw.argtypes=[ctypes.c_void_p,ctypes.c_int,ctypes.c_void_p,ctypes.c_int]
    p=trajectory(nodes); im=np.zeros((1024//scale,1024//scale),np.float32)
    lib.draw(p.ctypes.data,len(p),im.ctypes.data,scale)
    return im

def metrics(im,target):
    a=im>=.5;b=target>=.5
    return dict(iou=float((a&b).sum()/(a|b).sum()),precision=float((a&b).sum()/a.sum()),recall=float((a&b).sum()/b.sum()))

def main():
    build(); scale=2
    target=cv2.imread('/app/target.png',0)<128
    target=cv2.resize(target.astype(np.float32),(512,512),interpolation=cv2.INTER_AREA)
    dist=cv2.distanceTransform((target<.5).astype(np.uint8),cv2.DIST_L2,5)
    # extra ink weights especially outside tolerance
    weights=1.8+np.minimum(dist/2,2)
    nodes=INIT if not os.path.exists('/app/output/nodes.json') else json.load(open('/app/output/nodes.json'))
    ims=[render(n) for n in nodes]
    print('initial',metrics(np.maximum.reduce(ims),target),flush=True)
    for sweep in range(5):
      for i,n in enumerate(nodes):
        other=np.maximum.reduce([im for j,im in enumerate(ims) if j!=i])
        orig=np.array(n); shape=orig.shape
        def loss(flat):
            arr=flat.reshape(shape); im=np.maximum(other,render(arr))
            return float(np.sum(np.maximum(target-im,0))+np.sum(weights*np.maximum(im-target,0)))
        bounds=[]
        for x,y,w in orig:
            bounds.extend([(x-10,x+10),(y-10,y+10),(max(.2,w-12),min(70,w+12))])
        res=minimize(loss,orig.ravel(),method='Powell',bounds=bounds,options={'maxiter':4,'xtol':.2,'ftol':.0001})
        nodes[i]=res.x.reshape(shape).tolist();ims[i]=render(nodes[i]);
        print(sweep,i,round(res.fun,1),metrics(np.maximum.reduce(ims),target),flush=True)
        json.dump(nodes,open('/app/output/nodes.json','w'))
      im=np.maximum.reduce(ims)
      rgb=np.full((512,512,3),245,np.uint8);rgb[target>.5]=[180,150,150];rgb[im>.5]=[20,20,20]
      cv2.imwrite('/app/output/fit.png',rgb)
if __name__=='__main__':main()
